use super::tests::oid;
use super::*;
use crate::DomainError;
use proptest::prelude::*;

/// Real git 2.43.0 output, generated by `testdata/log.sh` (`sh log.sh testdata`) in a
/// temporary repo with `GIT_CONFIG_GLOBAL=/dev/null`, `GIT_CONFIG_NOSYSTEM=1`, fixed author, committer and
/// dates. The command that produces it is
///
/// ```sh
/// git log -z --date=raw --encoding=UTF-8 --no-show-signature --no-color \
///     --format='%H%x00%P%x00%an%x00%ae%x00%ad%x00%cn%x00%ce%x00%cd%x00%s%x00%b'
/// ```
///
/// that is, the arguments of [`LOG_ARGS`] (`--format=X` is equivalent to `--format=tformat:X`).
/// Five commits, most recent first: merge, declared Latin-1 message, undeclared Latin-1
/// author, multi-line body, root.
const LOG: &[u8] = include_bytes!("testdata/log.bin");

/// Same command as [`LOG`] on the empty range `HEAD..HEAD`: zero bytes.
const LOG_EMPTY: &[u8] = include_bytes!("testdata/log-empty.bin");

fn log() -> Vec<Commit> {
    parse_log(LOG).expect("valid real log")
}

fn reason(err: DomainError) -> String {
    match err {
        DomainError::InvalidGitOutput { command, reason } => {
            assert_eq!(command, "log");
            reason
        }
        other => panic!("unexpected error: {other:?}"),
    }
}

const ROOT: &str = "224ac11c4cfcc05f1bcd01a7e5531fe2b61143eb";

fn root_oid() -> Oid {
    oid(ROOT)
}

#[test]
fn reads_all_commits_in_order() {
    let commits = log();
    let summaries: Vec<&str> = commits.iter().map(|c| c.summary.as_str()).collect();
    assert_eq!(
        summaries,
        [
            "Merge side",
            "Café declared Latin-1",
            "Non-UTF-8 author",
            "Subject on two lines",
            "Root commit",
        ]
    );
    // Every commit except the root has the next commit on its branch as its parent.
    assert_eq!(commits[1].parents, [commits[2].id]);
    assert_eq!(commits[2].parents, [commits[3].id]);
    assert_eq!(commits[3].parents, [commits[4].id]);
}

#[test]
fn root_commit_without_parents_and_empty_body() {
    let root = log().pop().expect("at least one commit");
    assert_eq!(root.id, root_oid());
    assert!(root.parents.is_empty());
    assert!(!root.is_merge());
    assert_eq!(root.summary, "Root commit");
    assert_eq!(root.body, "");
    assert_eq!(
        root.author,
        Signature {
            name: "Anna Author".into(),
            email: "anna@example.com".into(),
            time: 1_700_000_000,
            offset_min: 120,
        }
    );
    assert_eq!(root.committer.name, "Carlo Committer");
    assert_eq!(root.committer.email, "carlo@example.com");
}

#[test]
fn merge_with_two_parents() {
    let commits = log();
    let merge = &commits[0];
    assert!(merge.is_merge());
    assert_eq!(merge.parents, [commits[3].id, commits[1].id]);
    assert_eq!(merge.body, "");
}

#[test]
fn multiline_body_and_joined_subject() {
    let c = &log()[3];
    // `%s` joins the lines of the first paragraph; `%b` is the rest, without the final newline.
    assert_eq!(c.summary, "Subject on two lines");
    assert_eq!(
        c.body,
        "First line of the body.\nSecond line of the body.\n\nSecond paragraph."
    );
    assert_eq!(c.parents, [root_oid()]);
}

#[test]
fn positive_negative_and_utc_time_zones() {
    let commits = log();
    let offsets: Vec<(i32, i32)> = commits
        .iter()
        .map(|c| (c.author.offset_min, c.committer.offset_min))
        .collect();
    assert_eq!(
        offsets,
        [
            (-7 * 60, 12 * 60 + 45),
            (60, 60),
            (-(3 * 60 + 30), 0),
            (5 * 60 + 30, -8 * 60),
            (120, 120),
        ]
    );
    // The seconds are UTC, independent of the time zone.
    assert_eq!(commits[0].author.time, 1_700_000_400);
    assert_eq!(commits[3].committer.time, 1_700_000_100);
}

#[test]
fn non_utf8_author_becomes_lossy_text() {
    let c = &log()[2];
    // The name in the commit is `Jos\xe9 Latin1` without an `encoding` header: git passes it
    // through as is and the parser makes it readable with `from_utf8_lossy`.
    assert_eq!(c.author.name, "Jos\u{fffd} Latin1");
    assert_eq!(c.author.email, "jose@example.com");
    assert_eq!(c.summary, "Non-UTF-8 author");
}

#[test]
fn declared_encoding_converted_by_git() {
    let c = &log()[1];
    // Commit with `encoding ISO-8859-1`: `--encoding=UTF-8` makes git convert it.
    assert_eq!(c.author.name, "Renée Encoding");
    assert_eq!(c.summary, "Café declared Latin-1");
    assert_eq!(c.body, "Body in Latin-1: café.");
}

#[test]
fn empty_output_no_commits() {
    assert!(LOG_EMPTY.is_empty());
    assert_eq!(parse_log(LOG_EMPTY), Ok(Vec::new()));
}

#[test]
fn args_contain_the_format() {
    assert!(LOG_ARGS.contains(&"-z"));
    assert!(LOG_ARGS.contains(&"--date=raw"));
    let format = format!("--format=tformat:{LOG_FORMAT}");
    assert!(LOG_ARGS.contains(&format.as_str()));
    assert_eq!(LOG_FORMAT.matches("%x00").count(), LOG_FIELDS - 1);
}

#[test]
fn commit_json() {
    let root = log().pop().expect("at least one commit");
    let json = serde_json::to_value(&root).expect("serializable");
    assert_eq!(json["id"], root_oid().to_string());
    assert_eq!(json["author"]["offset_min"], 120);
    let back: Commit = serde_json::from_value(json).expect("deserializable");
    assert_eq!(back, root);
}

// --- Malformed inputs -------------------------------------------------------------------

/// The first commit of the real log, as a record on its own (ten NUL-terminated fields).
fn first_record() -> Vec<u8> {
    let mut nul = 0;
    let end = LOG
        .iter()
        .position(|&b| {
            nul += usize::from(b == 0);
            nul == LOG_FIELDS
        })
        .expect("at least one record");
    LOG[..=end].to_vec()
}

fn with_field(idx: usize, value: &[u8]) -> Vec<u8> {
    let rec = first_record();
    let mut fields: Vec<&[u8]> = rec[..rec.len() - 1].split(|&b| b == 0).collect();
    fields[idx] = value;
    let mut out = fields.join(&0u8);
    out.push(0);
    out
}

#[test]
fn valid_isolated_record() {
    let commits = parse_log(&first_record()).expect("valid");
    assert_eq!(commits.len(), 1);
    assert_eq!(commits[0], log()[0]);
}

#[test]
fn error_if_the_final_nul_is_missing() {
    // Output truncated in the middle of a field (here the id of a sixth commit).
    let mut input = LOG.to_vec();
    input.extend_from_slice(b"224ac11c");
    assert!(reason(parse_log(&input).unwrap_err()).contains("does not end with NUL"));
    // Without the last NUL but with an empty body the input still ends with NUL: it results in one
    // field fewer.
    let mut input = first_record();
    input.pop();
    assert!(reason(parse_log(&input).unwrap_err()).contains("has 9 fields"));
}

#[test]
fn error_if_fields_are_missing() {
    let rec = first_record();
    let mut input = LOG.to_vec();
    // Second record with only three fields.
    input.extend_from_slice(b"a\0b\0c\0");
    let r = reason(parse_log(&input).unwrap_err());
    assert!(r.contains("commit 6 has 3 fields instead of 10"), "{r}");

    // One field fewer: the record does not close.
    let cut = rec.iter().rposition(|&b| b == 0).expect("nul");
    let short = &rec[..cut];
    let short = &short[..=short.iter().rposition(|&b| b == 0).expect("nul")];
    let r = reason(parse_log(short).unwrap_err());
    assert!(r.contains("commit 1 has 9 fields"), "{r}");
}

#[test]
fn error_if_the_id_is_invalid() {
    let r = reason(parse_log(&with_field(0, b"1234")).unwrap_err());
    assert!(r.contains("commit 1, field id (%H)"), "{r}");
    assert!(r.contains("`1234` is not a valid id"), "{r}");
}

#[test]
fn error_if_a_parent_is_invalid() {
    let mut parents = ROOT.as_bytes().to_vec();
    parents.extend_from_slice(b" zz");
    let r = reason(parse_log(&with_field(1, &parents)).unwrap_err());
    assert!(r.contains("field parents (%P)"), "{r}");
}

#[test]
fn error_if_the_date_is_invalid() {
    let cases_list: [(&[u8], &str); 6] = [
        (b"1700000000", "missing time zone"),
        (b"yesterday +0200", "seconds"),
        (b"-5 +0200", "seconds"),
        (b"1700000000 0200", "must start with `+` or `-`"),
        (b"1700000000 +200", "four digits"),
        (b"1700000000 +02x0", "time zone minutes"),
    ];
    for (data, expected_msg) in cases_list {
        let r = reason(parse_log(&with_field(4, data)).unwrap_err());
        assert!(r.contains("field author date (%ad)"), "{r}");
        assert!(r.contains(expected_msg), "{data:?}: {r}");
    }
    let r = reason(parse_log(&with_field(7, b"")).unwrap_err());
    assert!(r.contains("field committer date (%cd)"), "{r}");
}

// --- Properties --------------------------------------------------------------------------

/// Writes the commits as git would with [`LOG_ARGS`]; `%b` gets a trailing newline if not empty.
fn render(commits: &[Commit]) -> Vec<u8> {
    let mut out = Vec::new();
    for c in commits {
        let parents: Vec<String> = c.parents.iter().map(Oid::to_string).collect();
        let date = |s: &Signature| {
            let sign = if s.offset_min < 0 { '-' } else { '+' };
            let m = s.offset_min.abs();
            format!("{} {sign}{:02}{:02}", s.time, m / 60, m % 60)
        };
        let body = if c.body.is_empty() {
            String::new()
        } else {
            format!("{}\n", c.body)
        };
        let fields = [
            c.id.to_string(),
            parents.join(" "),
            c.author.name.clone(),
            c.author.email.clone(),
            date(&c.author),
            c.committer.name.clone(),
            c.committer.email.clone(),
            date(&c.committer),
            c.summary.clone(),
            body,
        ];
        for f in fields {
            out.extend_from_slice(f.as_bytes());
            out.push(0);
        }
    }
    out
}

fn arb_oid() -> impl Strategy<Value = Oid> {
    any::<[u8; 20]>().prop_map(Oid::from_bytes)
}

fn arb_signature() -> impl Strategy<Value = Signature> {
    (
        "[^\0]{0,12}",
        "[^\0]{0,12}",
        0i64..=4_000_000_000,
        -(99 * 60 + 59)..=(99 * 60 + 59),
    )
        .prop_map(|(name, email, time, offset_min)| Signature {
            name,
            email,
            time,
            offset_min,
        })
}

fn arb_commit() -> impl Strategy<Value = Commit> {
    (
        arb_oid(),
        prop::collection::vec(arb_oid(), 0..4),
        arb_signature(),
        arb_signature(),
        "[^\0\n]{0,20}",
        "([^\0]{0,30}[^\0\n])?",
    )
        .prop_map(|(id, parents, author, committer, summary, body)| Commit {
            id,
            parents,
            author,
            committer,
            summary,
            body,
        })
}

proptest! {
    #[test]
    fn round_trip_of_the_format(commits in prop::collection::vec(arb_commit(), 0..6)) {
        let parsed = parse_log(&render(&commits)).map_err(|e| TestCaseError::fail(e.to_string()))?;
        prop_assert_eq!(parsed, commits);
    }

    #[test]
    fn no_panic_on_arbitrary_bytes(input in prop::collection::vec(any::<u8>(), 0..400)) {
        let _ = parse_log(&input);
    }

    #[test]
    fn no_panic_on_altered_records(idx in 0..LOG_FIELDS, value in "[ -~]{0,50}") {
        let _ = parse_log(&with_field(idx, value.as_bytes()));
    }
}
